import { readFileSync } from 'node:fs';
import { expect, test } from '@nuxt/test-utils/playwright';
import type { Page } from '@playwright/test';

interface TestFixture {
  man: string;
  key: string;
  name: string;
  features: string[];
}

// Generated by `npm run build:test-fixtures`; see
// docs/superpowers/migration-audit.md for the feature matrix.
const fixtures = JSON.parse(
  readFileSync(new URL('../../test-fixtures.json', import.meta.url), 'utf8'),
) as TestFixture[];

// Redirect fixtures are covered by their own test, as their title and mode
// cards belong to the redirect target.
const redirectKeys = new Set(['stairville/mh-x30', 'uking/mini-gobo-moving-head-light']);
const regularFixtures = fixtures.filter((fixture) => !redirectKeys.has(`${fixture.man}/${fixture.key}`));

/**
 * Reads the manufacturer's display name from the site's API.
 * @param {Page} page - The Playwright page (shares the target site's base URL).
 * @param {string} manufacturerKey - Manufacturer key, e.g. `cameo`.
 * @returns {Promise<string>} The manufacturer name as rendered in titles.
 */
async function manufacturerName(page: Page, manufacturerKey: string): Promise<string> {
  const response = await page.request.get(`/api/v1/manufacturers/${manufacturerKey}`);
  expect(response.ok()).toBe(true);

  const manufacturer = await response.json() as { name: string };
  return manufacturer.name;
}

test('fixture pages show manufacturer and fixture name in title and heading', async ({ page, goto }) => {
  test.setTimeout(180_000);

  const manufacturerNames = new Map<string, string>();

  for (const fixture of regularFixtures) {
    let manufacturer = manufacturerNames.get(fixture.man);

    if (manufacturer === undefined) {
      manufacturer = await manufacturerName(page, fixture.man);
      manufacturerNames.set(fixture.man, manufacturer);
    }

    const response = await goto(`/${fixture.man}/${fixture.key}`, { waitUntil: 'load' });
    expect(response?.status(), `${fixture.man}/${fixture.key}`).toBe(200);

    await expect(page).toHaveTitle(new RegExp(
      `^${escapeRegExp(manufacturer)} ${escapeRegExp(fixture.name)} DMX fixture definition`,
    ));

    const heading = page.locator('h1').first();
    await expect(heading).toContainText(manufacturer);
    await expect(heading).toContainText(fixture.name);
  }
});

test('mode cards are limited to five by default and complete with ?loadAllModes', async ({ page, goto }) => {
  test.setTimeout(120_000);

  const modeCards = page.locator('.masonry-card-container > .card');
  const bigFixtureNotice = page.locator('.card.orange');
  const path = '/astera/fp3-hyperion-tube';

  await goto(path, { waitUntil: 'load' });
  await expect(modeCards).toHaveCount(5);
  await expect(bigFixtureNotice).toContainText('This fixture is big!');
  await expect(bigFixtureNotice).toContainText('Only the first 5 of 68 modes are displayed.');
  await expect(bigFixtureNotice.getByRole('link', { name: 'Load all 68 modes' })).toHaveAttribute('href', '?loadAllModes');
  // Client-only: rendered after mount, never part of the server HTML.
  await expect(bigFixtureNotice.getByRole('link', { name: 'Load 10 more modes' })).toBeVisible();

  await goto(`${path}?loadAllModes`, { waitUntil: 'load' });
  await expect(modeCards).toHaveCount(68);
  await expect(bigFixtureNotice).toHaveCount(0);
});

test('matrix section renders for fixtures with a matrix', async ({ page, goto }) => {
  await goto('/cameo/auro-beam-150', { waitUntil: 'load' });

  await expect(page.locator('h3.matrix')).toHaveText('Matrix');

  const matrix = page.locator('section.matrix');
  await expect(matrix).toBeVisible();
  expect(await matrix.locator('.pixel').count()).toBeGreaterThan(0);
  await expect(page.locator('section.wheels')).toHaveCount(0);

  // custom pixel group labels share the matrix component
  await goto('/glp/knv-arc', { waitUntil: 'load' });
  await expect(page.locator('section.matrix .pixel-groups h4')).toHaveText('Pixel groups');
  const pixelGroups = page.locator('section.matrix .pixel-groups section.pixel-group');
  expect(await pixelGroups.count()).toBeGreaterThan(0);
  await expect(pixelGroups.first().locator('.label')).toHaveText('Row 1');
  await expect(pixelGroups.first().locator('.value')).toHaveText('1, 2, 3, 4, 5');
});

test('wheel sections render with one figure per wheel', async ({ page, goto }) => {
  await goto('/ayrton/diablo-tc', { waitUntil: 'load' });

  await expect(page.locator('h3.wheels')).toHaveText('Wheels');

  const wheelSection = page.locator('section.wheels');
  await expect(wheelSection).toBeVisible();
  const figures = wheelSection.locator('figure.wheel');
  await expect(figures).toHaveCount(3);

  const summaries = wheelSection.locator('figure.wheel figcaption summary');
  expect(await summaries.allTextContents()).toEqual(['Color Wheel', 'Gobo Wheel', 'Animation Wheel']);

  const colorWheel = figures.first();
  expect(await colorWheel.locator('g.slot').count()).toBeGreaterThan(1);
  expect(await colorWheel.locator('figcaption tbody tr').count()).toBe(await colorWheel.locator('g.slot').count());
});

test('multi-color wheel slots render one pie segment per color', async ({ page, goto }) => {
  // Not part of the 22-fixture feature matrix: none of those has a slot with
  // more than one color, which is the only case where the wheel geometry differs.
  await goto('/eurolite/ts-2', { waitUntil: 'load' });

  const colorWheel = page.locator('figure.wheel').first();
  await expect(colorWheel.locator('figcaption summary')).toHaveText('Color Wheel');

  // Two two-color slots × two wedges each = four paths. The direction arrow
  // lives in `g.arrow`, outside the slot groups.
  expect(await colorWheel.locator('g.slot path').count()).toBe(4);
});

test('capability tables name null switch targets as No Function', async ({ page, goto }) => {
  await goto('/martin/mac-aura', { waitUntil: 'load' });

  const switchRows = page.locator('.capabilities-table tr.switch-to-channel');
  expect(await switchRows.count()).toBeGreaterThan(0);
  await expect(switchRows.first()).toContainText(/Channel\s+16\s+→\s+No Function/);
});

test('expand all and collapse all toggle the channel details', async ({ page, goto }) => {
  await goto('/robe/robin-viva-cmy', { waitUntil: 'load' });

  const openedDetails = page.locator('.mode-channels details[open]');
  await expect(openedDetails).toHaveCount(0);

  await page.locator('.icon-button.expand-all').first().click();
  await expect.poll(() => openedDetails.count()).toBeGreaterThan(0);

  await page.locator('.icon-button.collapse-all').first().click();
  await expect(openedDetails).toHaveCount(0);
});

test('help-wanted dialog opens and closes', async ({ page, goto }) => {
  await goto('/afx/lmh460z', { waitUntil: 'load' });

  const helpWanted = page.locator('.fixture-info .help-wanted');
  await expect(helpWanted).toContainText('You can help to improve this fixture definition!');

  await helpWanted.getByRole('link', { name: 'Send information' }).click();

  const dialog = page.locator('#help-wanted-dialog');
  await expect(dialog).toBeVisible();
  await expect(dialog).toHaveAttribute('aria-hidden', 'false');
  await expect(dialog.locator('h2')).toHaveText('Improve fixture');

  await dialog.getByRole('button', { name: 'Close' }).click();
  await expect(dialog).toHaveAttribute('aria-hidden', 'true');
  await expect(dialog).toBeHidden();
});

test('redirected fixtures land on the target URL with the same Location', async ({ page, goto, baseURL }) => {
  const redirects = [
    {
      from: '/cameo/ts60',
      to: '/cameo/ts-60-rgbw',
      redirectFrom: 'cameo%2Fts60',
      reason: 'The fixture was renamed.',
    },
    {
      from: '/uking/mini-gobo-moving-head-light',
      to: '/lixada/mini-gobo-moving-head-light',
      redirectFrom: 'uking%2Fmini-gobo-moving-head-light',
      reason: 'The fixture is the same but sold under different brands / names.',
    },
  ];

  for (const redirect of redirects) {
    const response = await page.request.get(redirect.from, { maxRedirects: 0 });
    expect(response.status(), redirect.from).toBe(302);

    const location = response.headers().location;
    const locationUrl = new URL(location, baseURL);
    expect(`${locationUrl.pathname}${locationUrl.search}`, redirect.from).toBe(
      `${redirect.to}?redirectFrom=${redirect.redirectFrom}`,
    );

    const navigation = await goto(redirect.from, { waitUntil: 'load' });
    expect(navigation?.status(), redirect.from).toBe(200);

    const landedUrl = new URL(page.url());
    expect(`${landedUrl.pathname}${landedUrl.search}`).toBe(
      `${redirect.to}?redirectFrom=${redirect.redirectFrom}`,
    );

    const notice = page.locator('section.card.yellow');
    await expect(notice).toContainText(`Redirected from ${redirect.from.slice(1)}`);
    await expect(notice).toContainText(redirect.reason);
  }
});

test('unknown manufacturer and unknown fixture both return 404', async ({ page, goto }) => {
  const unknownManufacturer = await goto('/nonexistent-manufacturer/some-fixture', { waitUntil: 'load' });
  expect(unknownManufacturer?.status()).toBe(404);

  const unknownFixture = await goto('/cameo/nonexistent-fixture', { waitUntil: 'load' });
  expect(unknownFixture?.status()).toBe(404);
});

test('fixture page renders without page-level console errors', async ({ page, goto }) => {
  const problems: string[] = [];

  page.on('pageerror', (error) => problems.push(`pageerror: ${error.message}`));
  page.on('console', (message) => {
    if (message.type() !== 'error' && message.type() !== 'warning') {
      return;
    }

    const text = message.text();

    // The sandbox certificate store does not trust the embetty server.
    if (/ERR_CERT_AUTHORITY_INVALID|embetty\.open-fixture-library\.org/.test(text)) {
      return;
    }

    problems.push(`${message.type()}: ${text}`);
  });

  await goto('/clay-paky/sharpy', { waitUntil: 'load' });
  await expect(page.locator('h1').first()).toContainText('Clay Paky Sharpy');

  // Limited-mode page: the "load more modes" button must not be rendered on
  // the server and then added on hydration.
  await goto('/astera/fp3-hyperion-tube', { waitUntil: 'load' });
  await expect(page.locator('h3.matrix')).toHaveText('Matrix');

  expect(problems).toEqual([]);
});

/**
 * Escapes regular expression metacharacters in a literal string.
 * @param {string} text - The literal text.
 * @returns {string} The text safe to embed in a RegExp.
 */
function escapeRegExp(text: string): string {
  return text.replaceAll(/[$()*+.?[\\\]^{|}]/g, '\\$&');
}
